package androidwacontacts_test

import (
	"testing"

	"github.com/rbenzing/minutiae/internal/parsers/androidwacontacts"
	"github.com/rbenzing/minutiae/internal/parsers/parsertest"
)

func runVariant(t *testing.T, variant string) parsertest.Result {
	t.Helper()
	h := parsertest.NewHarness(t)
	b := parsertest.LoadFixture(t, "testdata", variant).Bundle(h, remoteFor(variant))
	p := androidwacontacts.Parser{}
	return h.RunLenient(p, b.Input(h, p, false))
}

// The scenario oracle is generated by tools/fixtures/whatsapp_wadb.py from the spec's rules and shares no code with
// the parser: every record, warning and note it states must be what Parse produces. A variant that is reported
// unparsed (a backup, an encrypted file, no table) states no app and is covered by the probe tests.
func TestAndroidWAContactsMatchesOracle(t *testing.T) {
	parsed := 0
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		if fx.Expect.Notes["app"] == "" {
			continue
		}
		parsed++
		t.Run(v, func(t *testing.T) {
			h := parsertest.NewHarness(t)
			b := fx.Bundle(h, remoteFor(v))
			p := androidwacontacts.Parser{}
			res := h.RunLenient(p, b.Input(h, p, false))
			parsertest.AssertMatchesOracle(t, res, b, fx.Expect)
		})
	}
	if parsed != 4 {
		t.Errorf("%d variants are parsed, want wa-2.11, wa-current, wa-business and wa-deleted", parsed)
	}
}
